"use client";

import { useState } from "react";

const OMEGA = [1, 2, 3, 4, 5, 6];
const GENS = [[1, 2], [2, 3, 4], [5], [1, 3, 5]];
const FILLS = ["var(--accent)", "var(--success)", "var(--danger)", "var(--violet-300)", "var(--text-muted)", "var(--text)"];

/** The atoms of the sigma-algebra generated by some subsets of a six-point set. */
export function atoms(gens: number[][]): number[][] {
  const key = (x: number) => gens.map((g) => (g.includes(x) ? 1 : 0)).join("");
  const m = new Map<string, number[]>();
  OMEGA.forEach((x) => m.set(key(x), [...(m.get(key(x)) ?? []), x]));
  return [...m.values()];
}

/** Generate a sigma-algebra on six points from chosen sets. */
export function SigmaGenViz() {
  const [on, setOn] = useState([true, false, false, false]);
  const gens = GENS.filter((_, i) => on[i]);
  const A = atoms(gens);
  const atomOf = (x: number) => A.findIndex((a) => a.includes(x));
  const size = 2 ** A.length;
  return (
    <figure className="viz">
      <div className="viz-controls" style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
        {GENS.map((g, i) => (
          <button key={i} type="button" aria-pressed={on[i]} className={on[i] ? "btn btn-primary" : "btn btn-ghost"} onClick={() => setOn(on.map((v, j) => (j === i ? !v : v)))}>
            {"{"}{g.join(", ")}{"}"}
          </button>
        ))}
      </div>
      <svg viewBox="0 0 520 110" role="img" aria-label="Six points coloured by atom" style={{ width: "100%", display: "block", marginTop: 8 }}>
        {OMEGA.map((x, i) => (
          <g key={x}>
            <circle cx={60 + i * 80} cy={55} r={24} style={{ fill: FILLS[atomOf(x) % FILLS.length], stroke: "var(--bg)", strokeWidth: 2 }} />
            <text x={60 + i * 80} y={60} textAnchor="middle" style={{ fill: "var(--bg)", fontSize: 15, fontWeight: 700 }}>{x}</text>
          </g>
        ))}
      </svg>
      <p className="mono" style={{ fontSize: 13, fontWeight: 700 }}>
        generators: {gens.length ? gens.map((g) => `{${g.join(", ")}}`).join(", ") : "none"}. atoms: {A.map((a) => `{${a.join(", ")}}`).join(" ")}.
        The generated σ-algebra has 2{"⁰¹²³⁴⁵⁶⁷⁸⁹"[A.length]} = {size} sets, every union of atoms (of 64 subsets in all).
      </p>
      <figcaption className="viz-caption">
        Toggle the generating sets. Points with the same colour lie in exactly the same generators, so no set built by
        complements and unions can separate them. Those blocks are the atoms, and the σ-algebra is all their unions.
      </figcaption>
    </figure>
  );
}
